public int[][] allPairsViaDijkstra(int n, int[][] edges) {
    List<int[]>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) adj[e[0]].add(new int[]{e[1], e[2]});  // non-negative only

    int[][] result = new int[n][n];
    for (int s = 0; s < n; s++) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[s] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.offer(new long[]{0, s});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            if (top[0] > dist[(int) top[1]]) continue;
            for (int[] e : adj[(int) top[1]]) {
                if (dist[(int) top[1]] + e[1] < dist[e[0]]) {
                    dist[e[0]] = dist[(int) top[1]] + e[1];
                    pq.offer(new long[]{dist[e[0]], e[0]});
                }
            }
        }
        for (int j = 0; j < n; j++)
            result[s][j] = dist[j] == Long.MAX_VALUE ? -1 : (int) dist[j];
    }
    return result;
}

public int[][] floydWarshall(int n, int[][] edges) {
    final long INF = Long.MAX_VALUE / 4;   // headroom so INF + INF won't overflow
    long[][] dist = new long[n][n];
    for (long[] row : dist) Arrays.fill(row, INF);
    for (int i = 0; i < n; i++) dist[i][i] = 0;
    for (int[] e : edges) dist[e[0]][e[1]] = Math.min(dist[e[0]][e[1]], e[2]);

    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (dist[i][k] == INF) continue;          // no i→k path, skip row work
            for (int j = 0; j < n; j++) {
                if (dist[k][j] == INF) continue;
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    int[][] result = new int[n][n];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            result[i][j] = (i != j && dist[i][j] >= INF) ? -1 : (int) dist[i][j];
    return result;
}

