def floyd_warshall(self, n: int, edges: list[list[int]]) -> list[list[int]]:
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, w in edges:
        dist[u][v] = min(dist[u][v], w)

    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue                       # no i->k path
            row_i = dist[i]
            for j in range(n):
                if dik + dk[j] < row_i[j]:
                    row_i[j] = dik + dk[j]

    return [[-1 if i != j and dist[i][j] == INF else dist[i][j]
             for j in range(n)] for i in range(n)]

